function paginate(arr, pageSize, page) {
  const totalPages = Math.ceil(arr.length / pageSize)
  const start = (page - 1) * pageSize
  const data = arr.slice(start, start + pageSize)
  return { data, page, totalPages, total: arr.length }
}
